def parse_tasks(path: Path) -> list[dict]:
    text = path.read_text(encoding="utf-8-sig").strip()
    if text.startswith("[") and text.endswith("]"):
        return json.loads(text)
    tasks = []
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("{"):
            tasks.append(json.loads(line))
    return tasks
